<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import { api } from '../api';
import { type Row, statusNames, placementNames, adState, pollState, formatTime, localDateInput, fromLocalInput } from '../../shared/domain';
import Icon from './Icon.vue';
import { useRequestScope } from '../../shared/useRequestScope';
const props = defineProps<{ mode: 'activities' | 'ads' | 'polls'; user: Row | null; manage?: boolean; refreshKey?: number }>();
const emit = defineEmits<{ (event: 'join'): void; (event: 'updated'): void }>();
const rows = ref<Row[]>([]), mine = ref<Row[]>([]), managed = ref<Row[]>([]), tab = ref(props.manage && props.mode !== 'polls' ? 'manage' : props.mode === 'activities' ? 'mine' : 'public');
const error = ref(''), message = ref(''), busy = ref(false), loading = ref(false), modal = ref(''), form = ref<Row>({}), selected = ref<Row>({}), choices = ref<string[]>([]), dialog = ref<HTMLDialogElement | null>(null);
const staff = computed(() => props.user && ['superadmin', 'admin', 'organizer'].includes(props.user.role));
const currentRows = computed(() => tab.value === 'mine' ? mine.value : tab.value === 'manage' ? managed.value : rows.value);
let generation = 0, detailGeneration = 0;
const scope = useRequestScope();
onUnmounted(() => { ++generation; });
async function load() {
  const version = ++generation;loading.value = true;error.value = '';
  try {
    if (props.mode !== 'activities') { const data = await api(props.mode === 'ads' ? '/ads' : '/polls');if (version !== generation) return;rows.value = data; }
    if (props.user && props.mode !== 'polls') { const data = await api(props.mode === 'ads' ? '/my/ads' : '/my/event-proposals');if (version !== generation) return;mine.value = data; }
    if (staff.value && props.mode !== 'polls') { const data = await api(props.mode === 'ads' ? '/admin/ads' : '/admin/event-proposals');if (version !== generation) return;managed.value = data; }
  } catch (e) { if (version === generation) error.value = (e as Error).message; } finally { if (version === generation) loading.value = false; }
}
function member() { if (!props.user || props.user.status !== 'approved') { emit('join');return false; }return true; }
async function open(kind: string, data: Row = {}) { const current = scope.capture();const detailVersion = ++detailGeneration; form.value = { ...data };modal.value = kind;error.value = '';await nextTick();if (!current() || detailVersion !== detailGeneration) return;if (!dialog.value?.open) dialog.value?.showModal(); }
function close() { if (busy.value) return;++detailGeneration;dialog.value?.close();modal.value = ''; }
function create() { if (!member()) return;const dates = { startsAt: localDateInput(), endsAt: localDateInput(new Date(Date.now() + 7 * 86400000)) };open(props.mode === 'ads' ? 'ad' : 'poll', props.mode === 'ads' ? { title: '', sponsor: '', content: '', placement: 'home', url: '', contact: '', consent: false, ...dates } : { title: '', description: '', optionsText: '', maxChoices: 1, ...dates }); }
async function act(action: () => Promise<any>, text: string, keep = false) {
  if (busy.value) return;const current = scope.capture(), id = selected.value.id;busy.value = true;error.value = '';
  try { await action();if (!current()) return;busy.value = false;if (!keep) close();message.value = text;await load();if (current()) emit('updated'); }
  catch(e) { if (current()) error.value = (e as Error).message; }finally { if (current()) busy.value = false; }
}
function save() { act(() => api(props.mode === 'ads' ? '/ads' : '/polls', 'POST', { ...form.value, startsAt: fromLocalInput(form.value.startsAt), endsAt: fromLocalInput(form.value.endsAt), ...(props.mode === 'polls' ? { options: form.value.optionsText.split('\n').map((v: string) => v.trim()).filter(Boolean), maxChoices: Number(form.value.maxChoices) } : {}) }), props.mode === 'ads' ? '广告申请已提交审核' : '投票已发布'); }
function detail(row: Row) { selected.value = row;choices.value = [...(row.myChoices || [])];open(props.mode === 'polls' ? 'vote' : 'detail'); }
function review(row: Row) { selected.value = row;open('review', { status: 'approved', note: '' }); }
function confirm(path: string, text: string) { open('confirm', { path, text }); }
watch([() => props.mode, () => props.user?.id, () => props.manage, () => props.refreshKey, () => props.user?.status, () => props.user?.role], () => { scope.invalidate();++detailGeneration;busy.value = false;selected.value = {};form.value = {};error.value = '';dialog.value?.close();modal.value = '';message.value = '';choices.value = [];++generation;rows.value = [];mine.value = [];managed.value = [];tab.value = props.manage && props.mode !== 'polls' ? 'manage' : props.mode === 'activities' ? 'mine' : 'public';load(); }, { flush: 'sync' });
onMounted(load);
</script>
<template>
  <section class="engagement-hub" :aria-busy="loading"><p v-if="error && !modal" class="form-error" role="alert">{{ error }}<button class="text-button" :disabled="loading" @click="load">重新加载</button></p><p v-if="loading && !modal" role="status">正在加载…</p><p v-if="message" class="status-note" role="status">{{ message }}</p>
    <div class="filterbar"><div class="chips"><button v-if="mode !== 'activities'" :class="{ selected: tab === 'public' }" @click="tab = 'public'">{{ mode === 'polls' ? '会员投票' : '当前展示' }}</button><button v-if="user && mode !== 'polls'" :class="{ selected: tab === 'mine' }" @click="tab = 'mine'">{{ mode === 'ads' ? '我的投放申请' : '我的活动发起' }}</button><button v-if="staff && mode !== 'polls'" :class="{ selected: tab === 'manage' }" @click="tab = 'manage'">{{ mode === 'ads' ? '投放审核与排期' : '活动发起审核' }}</button></div><button v-if="mode === 'ads' || (mode === 'polls' && staff)" class="primary" @click="create"><Icon name="plus"/>{{ mode === 'ads' ? '申请广告展示' : '发起投票' }}</button></div>
    <p v-if="mode === 'ads'" class="form-tip">广告由平台人工审核，按批准的起止时间展示。当前不提供支付或自动计费；广告均明确标识。</p><p v-if="mode === 'polls'" class="form-tip">通过审核的会员可参与；每场仅提交一次，不公开个人选择。投票后或结束后，已审核会员可查看汇总结果。</p>
    <div v-if="!loading && !error && !currentRows.length && (mode !== 'activities' || user)" class="empty"><h3>{{ mode === 'polls' ? '一起商量，一起决定' : mode === 'ads' ? '让有用的信息被看见' : '还没有活动发起记录' }}</h3><p>{{ mode === 'polls' ? '投票发布后，你可以在这里表达意见。' : mode === 'ads' ? '提交真实的合作信息，审核通过后按排期展示。' : '点击活动页的“发起活动”，说说你的计划。' }}</p></div>
    <div class="cards-grid"><article v-for="row in currentRows" :key="row.id" class="post-card"><div class="hub-row"><span class="tag">{{ mode === 'polls' ? pollState(row) : mode === 'ads' ? tab === 'public' ? '展示中' : adState(row) : statusNames[row.status] }}</span><small>{{ mode === 'ads' ? placementNames[row.placement] : mode === 'polls' ? row.maxChoices === 1 ? '单选' : '最多选' + row.maxChoices + '项' : row.category }}</small></div><h3><button class="plain" @click="detail(row)">{{ row.title }}</button></h3><p class="excerpt">{{ row.description || row.content }}</p><p v-if="mode === 'ads'" class="meta">{{ row.sponsor }}</p><p v-if="mode === 'activities'" class="meta">发起人：{{ row.authorName }} · {{ row.capacity }}人</p><p class="meta">{{ formatTime(row.startsAt) }} — {{ formatTime(row.endsAt) }}</p><p v-if="row.reviewNote" class="form-tip">处理说明：{{ row.reviewNote }}</p><div class="card-footer"><span>{{ mode === 'polls' ? row.hasVoted ? '你已投票' : '听听你的想法' : mode === 'ads' ? '人工审核 · 无在线支付' : row.eventId ? '已转为正式活动' : '审核后公开报名' }}</span><button class="text-button" @click="detail(row)">{{ mode === 'polls' ? row.resultsVisible ? '查看结果' : '查看投票' : '查看详情' }}</button></div><div class="button-row"><button v-if="tab === 'manage' && row.status === 'pending'" class="text-button" @click="review(row)">审核申请</button><button v-if="mode === 'ads' && tab !== 'public' && ['pending', 'approved'].includes(row.status)" class="text-button" @click="confirm('/ads/' + row.id + '/withdraw', '确认撤下这条广告？撤下后立即停止公开展示。')">撤下广告</button><button v-if="mode === 'polls' && staff && !row.ended" class="text-button" @click="confirm('/polls/' + row.id + '/close', '确认提前结束投票？结束后不能继续投票，已有结果保留。')">结束投票</button></div></article></div>
    <dialog ref="dialog" class="modal" aria-label="活动广告投票操作" @cancel.prevent="close"><div class="modal-inner"><header><h2>{{ modal === 'ad' ? '申请广告展示' : modal === 'poll' ? '发起会员投票' : modal === 'review' ? '审核申请' : modal === 'confirm' ? '确认操作' : selected.title }}</h2><button class="close-button" :disabled="busy" aria-label="关闭操作" @click="close">×</button></header><p v-if="error" class="form-error" role="alert">{{ error }}</p>
      <form v-if="modal === 'ad' || modal === 'poll'" @submit.prevent="save"><label>标题<input v-model="form.title" required minlength="2" :maxlength="modal === 'ad' ? 60 : 80"></label><template v-if="modal === 'ad'"><label>广告主 / 合作方名称<input v-model="form.sponsor" required minlength="2" maxlength="60"></label><label>广告内容<textarea v-model="form.content" required minlength="10" maxlength="800" rows="5"></textarea></label><label>展示位置<select v-model="form.placement"><option value="home">首页推荐位</option><option value="events">活动页面</option></select></label><label>详情链接（HTTPS，可不填）<input v-model="form.url" type="url" maxlength="500" placeholder="https://"></label><label>公开联系方式（选填）<input v-model="form.contact" maxlength="80"></label></template><template v-else><label>投票说明<textarea v-model="form.description" maxlength="2000" rows="3"></textarea></label><label>选项（每行一项，2至10项）<textarea v-model="form.optionsText" required rows="6" placeholder="周六上午&#10;周六下午&#10;周日上午"></textarea></label><label>最多可选数量<input v-model="form.maxChoices" required type="number" min="1" max="10"></label></template><div class="form-grid"><label>开始时间（北京时间）<input v-model="form.startsAt" required type="datetime-local"></label><label>结束时间（北京时间）<input v-model="form.endsAt" required type="datetime-local"></label></div><label v-if="modal === 'ad'" class="checkbox"><input v-model="form.consent" required type="checkbox">我确认内容真实，并同意公开展示所填合作方和联系信息。</label><p class="form-tip">{{ modal === 'ad' ? '审核通过后按所填时间展示；最长180天，不涉及在线付款。' : '发布后不能改动问题或选项；可提前结束。只展示统计，不公开个人选择。' }}</p><button class="primary full" :disabled="busy">{{ modal === 'ad' ? '提交广告审核' : '发布投票' }}</button></form>
      <div v-if="modal === 'detail'"><p v-if="mode === 'ads'"><span class="tag">广告</span> {{ selected.sponsor }} · {{ placementNames[selected.placement] }}</p><p class="prose">{{ selected.description || selected.content }}</p><p v-if="mode === 'activities'">地点：{{ selected.location }}<br>人数：{{ selected.capacity }} · 发起人：{{ selected.authorName }}</p><p class="meta">{{ formatTime(selected.startsAt) }} — {{ formatTime(selected.endsAt) }}（北京时间）</p><p v-if="mode === 'ads'" class="status-note">{{ selected.contact || '未填写联系方式' }}</p><a v-if="mode === 'ads' && selected.url" :href="selected.url" target="_blank" rel="noopener noreferrer sponsored" class="text-button">打开广告详情 ↗</a></div>
      <form v-if="modal === 'review'" @submit.prevent="act(() => api((mode === 'ads' ? '/ads/' : '/event-proposals/') + selected.id + '/review', 'POST', form), '审核结果已保存')"><h3>{{ selected.title }}</h3><p class="prose">{{ selected.description || selected.content }}</p><p v-if="mode === 'activities'">{{ selected.location }} · {{ selected.capacity }}人 · {{ selected.authorName }}</p><p v-if="mode === 'ads'">{{ selected.sponsor }} · {{ placementNames[selected.placement] }}<br>{{ selected.url }}<br>{{ selected.contact }}</p><p class="meta">{{ formatTime(selected.startsAt) }} — {{ formatTime(selected.endsAt) }}</p><label>审核结果<select v-model="form.status"><option value="approved">通过并按计划发布</option><option value="rejected">退回</option></select></label><label>审核说明<textarea v-model="form.note" :required="form.status === 'rejected'" :minlength="form.status === 'rejected' ? 2 : 0" maxlength="300" rows="3"></textarea></label><button class="primary full" :disabled="busy">确认审核</button></form>
      <div v-if="modal === 'vote'"><span class="tag">{{ pollState(selected) }} · {{ selected.maxChoices === 1 ? '单选' : '最多选择' + selected.maxChoices + '项' }}</span><p class="prose">{{ selected.description }}</p><p class="meta">截止 {{ formatTime(selected.endsAt) }}（北京时间）</p><form @submit.prevent="member() && act(() => api('/polls/' + selected.id + '/vote', 'POST', { choices }), '投票已提交')"><label v-for="option in selected.options" :key="option.id" class="poll-option"><input v-model="choices" type="checkbox" :value="option.id" :disabled="selected.hasVoted || selected.ended || pollState(selected) !== '投票中'"><span>{{ option.text }}</span><b v-if="selected.resultsVisible">{{ selected.counts[option.id] || 0 }} 票</b></label><p v-if="selected.resultsVisible" class="status-note">共有 {{ selected.totalVotes }} 位会员投票。{{ selected.maxChoices > 1 ? '多选票数合计可能大于投票人数。' : '' }}</p><p v-if="selected.hasVoted" class="form-tip">你已投票，个人选择不对其他会员公开。</p><button v-if="!selected.hasVoted && !selected.ended" class="primary full" :disabled="busy || !choices.length || choices.length > selected.maxChoices || pollState(selected) !== '投票中'">确认投票（提交后不可更改）</button></form></div>
      <div v-if="modal === 'confirm'"><p class="prose">{{ form.text }}</p><div class="button-row"><button class="outline" @click="close">返回</button><button class="primary" :disabled="busy" @click="act(() => api(form.path, 'POST'), '操作已完成')">确认</button></div></div>
    </div></dialog>
  </section>
</template>
<style scoped>
.engagement-hub{margin:24px 0}.hub-row{display:flex;justify-content:space-between;gap:10px;align-items:center}.poll-option{display:flex!important;flex-direction:row!important;align-items:center;gap:12px!important;padding:15px;border:1px solid #dce8e4;border-radius:7px;margin:12px 0!important}.poll-option input{width:17px!important;min-height:17px;flex:0 0 auto;accent-color:#174d6b}.poll-option span{flex:1;overflow-wrap:anywhere}.poll-option b{font-size:12px;color:#4d8d80;white-space:nowrap}
</style>
